def is_palindrome(s):
    t = s.replace(' ', '')
    return t == t[::-1]

def factorial(n):
    if n < 2:
        return 1
    return n * factorial(n - 1)

def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        need = target - x
        if need in seen:
            return [seen[need], i]
        seen[x] = i
